<?php
declare(strict_types=1);

// Usage:
// php bin/release.php --product=transport-cms --version=1.1.0
//   --package=/private/releases/transport-cms-1.1.0.zip --channel=stable
// The package is never web-extracted by this command.
if (PHP_SAPI !== 'cli') { fwrite(STDERR,"CLI only\n"); exit(1); }
$root=dirname(__DIR__);
foreach([$root.'/.env',dirname($root).'/.env'] as $env) if(is_file($env)) foreach(file($env,FILE_IGNORE_NEW_LINES) as $line) if(preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/',trim($line),$m)&&getenv($m[1])===false)putenv($m[1].'='.trim(trim($m[2]),"\"'"));
function arg(string $name,string $default=''): string { global $argv; foreach($argv as $value)if(str_starts_with($value,'--'.$name.'='))return substr($value,strlen($name)+3);return $default; }
$product=arg('product');$version=arg('version');$package=arg('package');$channel=arg('channel','stable');$changelog=arg('changelog','');$minPhp=arg('min-php','8.2.0');$migration=(int)arg('migration','0');
if(!preg_match('/^[a-z0-9][a-z0-9._-]{1,80}$/',$product)||!preg_match('/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/',$version)||!in_array($channel,['preview','beta','stable'],true)||!is_file($package)){fwrite(STDERR,"Usage: --product=slug --version=x.y.z --package=/private/file.zip [--channel=stable] [--changelog=text]\n");exit(2);}
$dbPath=getenv('LICENSE_DB_PATH')?:$root.'/storage/licenses.sqlite';if(!is_dir(dirname($dbPath)))mkdir(dirname($dbPath),0700,true);$db=new PDO('sqlite:'.$dbPath,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec("CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'application',status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS application_releases(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,version TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'stable',package_name TEXT NOT NULL,package_path TEXT NOT NULL,manifest_json TEXT NOT NULL,sha256 TEXT NOT NULL,signature TEXT NOT NULL,min_php TEXT NOT NULL DEFAULT '8.2.0',migration_version INTEGER NOT NULL DEFAULT 0,changelog TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TEXT,UNIQUE(product_id,version,channel));");
$productRow=$db->prepare('SELECT * FROM products WHERE slug=?');$productRow->execute([$product]);$row=$productRow->fetch();if(!$row){$insert=$db->prepare("INSERT INTO products(slug,name,kind,status) VALUES(?,?, 'application','published')");$insert->execute([$product,$product]);$id=(int)$db->lastInsertId();}else$id=(int)$row['id'];
$sha=hash_file('sha256',$package);$manifest=['product'=>$product,'version'=>$version,'channel'=>$channel,'package'=>basename($package),'sha256'=>$sha,'min_php'=>$minPhp,'migration_version'=>$migration,'created_at'=>gmdate('c')];$manifestJson=json_encode($manifest,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$secret=getenv('RELEASE_SIGNING_SECRET')?:'';if(strlen($secret)<32){fwrite(STDERR,"RELEASE_SIGNING_SECRET must contain at least 32 characters.\n");exit(3);}$signature=hash_hmac('sha256',$manifestJson,$secret);
$statement=$db->prepare("INSERT INTO application_releases(product_id,version,channel,package_name,package_path,manifest_json,sha256,signature,min_php,migration_version,changelog,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'published',CURRENT_TIMESTAMP) ON CONFLICT(product_id,version,channel) DO UPDATE SET package_name=excluded.package_name,package_path=excluded.package_path,manifest_json=excluded.manifest_json,sha256=excluded.sha256,signature=excluded.signature,min_php=excluded.min_php,migration_version=excluded.migration_version,changelog=excluded.changelog,status='published',published_at=CURRENT_TIMESTAMP");$statement->execute([$id,$version,$channel,basename($package),realpath($package)?:$package,$manifestJson,$sha,$signature,$minPhp,$migration,$changelog]);fwrite(STDOUT,"Published $product $version ($channel)\nSHA256: $sha\nSignature: $signature\n");
